"""Numbers: the cost C of every package, the floor and anchor per supplier, probe sheets that
trade price against the lever a supplier values, the concession schedule and the closing gate.
Nothing here calls a model; every figure that reaches a term sheet is computed here."""

import math

from arena_kit.cost import complete_offer, must_haves_ok, total_cost

GOAL_CAPTURE = {"leverage": 0.75, "routine": 0.5, "stabilise": 0.6, "secure_supply": 0.55, "quality_first": 0.65}
OPENING_GAP = {"strategic": 0.05, "important": 0.08, "standard": 0.12}
# Outside stabilise and secure_supply the arena charges nothing for the supplier's margin;
# this is the margin we still leave an important supplier on its estimated full cost.
TIER_MARGIN = {"strategic": 4.0, "important": 2.0, "standard": 0.0}
# Price increase: the share of the justified increase we concede in the opening sheet, by tier.
JUSTIFIED_SHARE = {"strategic": 0.5, "important": 0.25, "standard": 0.0}
STEPS = [0.35, 0.25, 0.15, 0.10]
# Which value of a lever is a sweetener for the supplier (the probe sheet moves it there).
SUPPLIER_FRIENDLY = {
    "payment_days": min,
    "contract_months": max,
    "volume_per_year": max,
    "lead_time_days": max,
    "tooling_eur": max,
    "effective_date": min,
    "ppm_commitment": max,
    "chargeback_eur_per_complaint": min,
}


def cost(case, terms, std=None, est=None):
    try:
        return total_cost(case, terms, std, est)
    except (KeyError, TypeError, ValueError):
        return math.inf


def c_alt(case):
    alt = case.get("buyer", {}).get("alternative") or {}
    terms = alt.get("terms") or {}
    return cost(case, terms) if alt.get("kind") not in (None, "none") and terms.get("unit_price") else math.inf


def gate_ok(case, terms, std, est=None):
    """The accept gate: must-haves hold and the deal beats the alternative (when one exists)."""
    return (
        bool(terms.get("unit_price")) and must_haves_ok(case, terms, std) and cost(case, terms, std, est) < c_alt(case)
    )


def supplier_estimate(pkg, case, persona, std, quote_price):
    """Our estimate of the supplier for the relationship term: full cost per unit and its cost of money."""
    part = (case.get("parts") or [None])[0]
    n = persona["supplier_id"].split(":")[-1]
    fact, source = None, "assumed"
    if part:
        pn = part.split(":")[-1]
        facts = case.get("facts") or {}
        for ref, specific in ((f"cost:{pn}-{n}", True), (f"cost:{pn}", False)):
            f = facts.get(ref) or (pkg.lookup(ref) if pkg else None)
            if f and f.get("unit_cost"):
                fact, source = f, "should_cost" + ("" if specific else " (DE base)")
                factor = 1.0 if specific else persona.get("estimate", {}).get("country_factor", 1.0)
                full_cost = f["unit_cost"] * factor
                break
    if fact is None:
        if not quote_price:
            return None
        full_cost = quote_price * 0.88  # no should-cost: assume a 12 % margin in the quote
    return {
        "full_cost": round(full_cost, 2),
        "interest_rate": persona.get("estimate", {}).get("interest_rate", 0.08),
        "standard": std or {},
        "source": source,
    }


def floor_price(case, persona, est, quote_price):
    """The lowest price we ever write into a sheet: the supplier's estimated full cost plus the
    margin we leave it, and never a fantasy figure far below its quote."""
    guard = persona.get("relationship", {})
    goal = case.get("buyer", {}).get("category_goal")
    if goal in ("stabilise", "secure_supply"):
        # the arena itself charges for every margin point below the sustainable margin
        margin = max(guard.get("min_margin_pct", 2.0), case["buyer"].get("sustainable_margin_pct") or 0)
    else:
        margin = TIER_MARGIN.get(persona.get("importance", {}).get("tier"), 0.0)
    if est and est.get("source", "").startswith("should_cost"):
        floor = est["full_cost"] / (1 - margin / 100)
    else:
        floor = (quote_price or 0) * (0.90 if not guard.get("protect") else 0.94)
    if quote_price:
        ceiling = quote_price if goal in ("stabilise", "secure_supply") else quote_price * 0.97
        floor = min(max(floor, quote_price * 0.80), ceiling)
    return round(floor, 2)


def justified_increase_pct(bank, part):
    """Σ driver weight × the driver's 12-month change: what a price letter may legitimately ask."""
    changes = bank.driver_changes(part)
    return round(sum(w * pct for _, w, pct in changes), 2) if changes else None


def anchor_price(case, persona, floor, quote_price, justified_pct=None):
    """Round-1 price: the justified increase on the current price in a price case, else a
    deliberate gap below the quote - but never below the floor and never above the quote."""
    tier = persona.get("importance", {}).get("tier", "standard")
    goal = case.get("buyer", {}).get("category_goal")
    current = case.get("buyer", {}).get("current_unit_price")
    if case.get("type") == "price_increase" and current:
        share = JUSTIFIED_SHARE.get(tier, 0.0)
        anchor = current * (1 + share * max(0.0, justified_pct or 0.0) / 100)
    else:
        gap = OPENING_GAP.get(tier, 0.12)
        if goal == "routine":
            gap = min(gap, 0.06)
        anchor = quote_price * (1 - gap)
    anchor = max(floor, min(anchor, quote_price * 0.985))
    return round(anchor, 2)


def best_nonprice(case, std, est=None, price=None):
    """For every negotiable field but the price: the option that costs us least (ties: first)."""
    probe = price or case.get("buyer", {}).get("current_unit_price") or 1.0
    terms = complete_offer(case, {"unit_price": probe})
    for field in case.get("negotiable", []):
        options = case.get("term_options", {}).get(field)
        if field == "unit_price" or not options:
            continue
        terms[field] = min(options, key=lambda o: cost(case, {**terms, field: o}, std, est))
    return terms


def solve_price(case, terms, std, est, target_c, lo, hi):
    """The unit price at which `terms` cost us `target_c`: C rises with price, so bisect."""
    lo, hi = min(lo, hi), max(lo, hi)
    for _ in range(40):
        mid = (lo + hi) / 2
        if cost(case, {**terms, "unit_price": mid}, std, est) > target_c:
            hi = mid
        else:
            lo = mid
    return round(lo, 2)


def sheets(case, persona, std, est, price, levers, floor, standing=None, hold=None):
    """Up to three sheets: A at `price` with our best terms, then one variant per lever that moves
    the lever to the supplier's side at the same C for us. `hold` pins fields the supplier already
    answered. Every sheet is complete, keeps the must-haves and costs less than the standing offer."""
    base = {**best_nonprice(case, std, est, price), **(hold or {})}
    a = complete_offer(case, {**base, "unit_price": price})
    c_a = cost(case, a, std, est)
    out = [a]
    for lever in levers:
        options = case.get("term_options", {}).get(lever)
        if lever == "unit_price" or lever not in case.get("negotiable", []) or lever in (hold or {}):
            continue
        if lever == "index_clause":
            clauses = [o for o in options or [] if o]
            if not clauses:
                continue
            value = clauses[0]
        elif lever == "incoterm":
            freight = case["buyer"]["freight_eur_per_unit"]
            value = max(freight, key=freight.get)
        elif options:
            pick = SUPPLIER_FRIENDLY.get(lever, max)
            value = pick(options)
            if value == a.get(lever):
                continue
        else:
            continue
        variant = {**a, lever: value}
        lo = floor if lever not in ("ppm_commitment", "chargeback_eur_per_complaint") else price
        v_price = solve_price(case, variant, std, est, c_a, lo * 0.9, max(price * 1.3, lo))
        variant = complete_offer(case, {**variant, "unit_price": max(v_price, floor * 0.97)})
        if variant not in out:
            out.append(variant)
        if len(out) >= 3:
            break
    keep = []
    c_std = cost(case, standing, std, est) if standing else math.inf
    for s in out:
        if must_haves_ok(case, s, std) and cost(case, s, std, est) < c_std:
            keep.append(s)
    return keep or [a]


def concession(ours_last, theirs, round_idx, moved, close_in=False):
    """Our next price toward theirs: a falling share of the gap, only after they moved."""
    if ours_last is None or theirs is None or theirs <= ours_last:
        return ours_last
    if not moved and not close_in:
        return ours_last
    step = 0.6 if close_in else STEPS[min(round_idx, len(STEPS) - 1)]
    return round(min(theirs, ours_last + step * (theirs - ours_last)), 2)


def target_cost(case, c_open, c_anchor, c_cap=None):
    """Where we stop pushing: the share of the opening gap the category goal asks us to capture,
    and never above `c_cap` (a price increase: C at the justified price)."""
    goal = case.get("buyer", {}).get("category_goal", "leverage")
    target = c_open - GOAL_CAPTURE.get(goal, 0.6) * (c_open - c_anchor)
    return min(target, c_cap) if c_cap is not None else target


def describe(case, sheet):
    """A term sheet in plain words, for the e-mail (figures exactly as in the sheet)."""
    parts = [f"EUR {sheet['unit_price']:.2f} per unit"] if sheet.get("unit_price") is not None else []
    labels = {
        "payment_days": lambda v: f"payment {v} days net",
        "contract_months": lambda v: f"{v} months" if v else "a single order",
        "volume_per_year": lambda v: f"{v:,} units a year",
        "lead_time_days": lambda v: f"lead time {v} days",
        "effective_date": lambda v: f"valid from {v}",
        "incoterm": lambda v: f"{v}" + (" Hollerau" if v == "DAP" else ""),
        "tooling_eur": lambda v: f"tooling EUR {v:,.0f}" if v else "no tooling charge",
        "ppm_commitment": lambda v: f"{v} ppm",
        "chargeback_eur_per_complaint": lambda v: f"EUR {v:,.0f} per complaint",
        "index_clause": lambda v: (
            f"price follows {v['series']} on {int(v['material_share'] * 100)}% of the price, "
            f"deadband {v['deadband_pct']}%"
            if v
            else "fixed price"
        ),
    }
    for field in case.get("negotiable", []):
        if field in labels and field in sheet:
            parts.append(labels[field](sheet[field]))
    return ", ".join(parts)


def supplier_side(case, lever, ours):
    """The value of a lever on the supplier's side, or None if there is nothing to trade."""
    options = case.get("term_options", {}).get(lever)
    if lever == "index_clause":
        clauses = [o for o in options or [] if o]
        return clauses[0] if clauses and ours != clauses[0] else None
    if lever == "incoterm":
        freight = case["buyer"]["freight_eur_per_unit"]
        theirs = max(freight, key=freight.get)
        return theirs if theirs != ours else None
    if options:
        theirs = SUPPLIER_FRIENDLY.get(lever, max)(options)
        return theirs if theirs != ours else None
    return None


def lever_analysis(case, persona, std, est, price, c_open, bank_claims=(), justified=None, asked=None, rivals=0):
    """What we can trade and what we can argue, before the first move, ranked: cheap for us and
    valuable to the supplier first. Term levers carry the C they cost us; argument levers the
    reason they weigh."""
    base = best_nonprice(case, std, est, price)
    a = complete_offer(case, {**base, "unit_price": price})
    c_a = cost(case, a, std, est)
    ranked = persona.get("levers", [])
    learned = (persona.get("learned") or {}).get("lever_answered") or {}
    out = []
    for lever in case.get("negotiable", []):
        if lever == "unit_price":
            continue
        theirs = supplier_side(case, lever, a.get(lever))
        if theirs is None:
            continue
        delta = cost(case, complete_offer(case, {**a, lever: theirs}), std, est) - c_a
        share = delta / c_open if c_open and c_open < math.inf else 0.0
        pos = ranked.index(lever) if lever in ranked else None
        value = {0: 3.0, 1: 2.0}.get(pos, 1.0 if pos is not None else 0.5) + min(2.0, 0.5 * learned.get(lever, 0))
        score = value * max(0.1, 1 - 20 * max(share, 0.0))
        why = f"{persona.get('archetype')} values it" if pos is not None and pos < 2 else "no sign they value it"
        if learned.get(lever):
            why += f"; answered it {learned[lever]}x before"
        out.append(
            {
                "kind": "term",
                "lever": lever,
                "ours": a.get(lever),
                "theirs": theirs,
                "delta_c": round(delta),
                "delta_share_pct": round(100 * share, 2),
                "value_to_them": value,
                "score": round(score, 2),
                "why": why,
            }
        )
    strong = [c for c in bank_claims if c.get("for_us")]
    if strong:
        themes = sorted({c["theme"] for c in strong})
        out.append(
            {
                "kind": "argument",
                "lever": "data",
                "score": round(min(2.0, 0.5 * len(strong)), 2),
                "why": f"{len(strong)} verified-ready arguments: {', '.join(themes)}",
            }
        )
    notice = next((c for c in bank_claims if c["kind"] == "notice" and c["for_us"]), None)
    if notice:
        out.append({"kind": "argument", "lever": "notice", "score": 3.0, "why": notice["sentence"]})
    if justified is not None and asked is not None and asked > justified:
        out.append(
            {
                "kind": "argument",
                "lever": "justified_increase",
                "score": round(min(3.0, (asked - justified) / 2), 2),
                "why": f"they ask {asked:+.1f}%, the cost drivers justify {justified:+.1f}%",
            }
        )
    alt = c_alt(case)
    if alt < c_open:
        out.append(
            {
                "kind": "argument",
                "lever": "alternative",
                "score": 3.0,
                "why": f"our alternative costs EUR {alt:,.0f} against EUR {c_open:,.0f} for the opening",
            }
        )
    if rivals:
        out.append(
            {"kind": "argument", "lever": "competition", "score": 2.5, "why": f"{rivals} other bidder(s) in this case"}
        )
    return sorted(out, key=lambda r: -r["score"])


def lever_line(r):
    """One line per lever, for logs and the plan command."""
    if r["kind"] == "term":
        return (
            f"{r['lever']}: ours {r['ours']} -> theirs {r['theirs']}, costs us EUR {r['delta_c']:,} "
            f"({r['delta_share_pct']}% of C), value to them {r['value_to_them']} -> score {r['score']} ({r['why']})"
        )
    return f"{r['lever']}: {r['why']} -> score {r['score']}"
=====CLAIMS
"""Claim bank: pre-verified data arguments, each one sentence with its figure next to its IDs.

The arena checks every cited ID against facts.json and the case's own facts; a wrong figure or an
unknown ID is `contradicted` and costs trust. So every figure is computed here exactly as the
arena computes it, and the model only chooses the wording around the sentences it is given.
"""

import re

SERIES_THEME = {
    "PPI-D351": "energy",
    "PPI-D35": "energy",
    "SMARD-DA": "energy",
    "WB-NGEU": "energy",
    "LCI-C": "labour",
    "PPI-C241": "material",
    "PPI-C2431": "material",
    "WB-CU": "material",
    "WB-NI": "material",
    "WB-AL": "material",
    "WB-FEORE": "material",
    "CU-NOTATION": "material",
    "AS-14404": "material",
    "AS-14301": "material",
}
SERIES_NAME = {
    "PPI-C2451": "Producer prices for iron castings",
    "PPI-C2452": "Producer prices for steel castings",
    "PPI-C2562": "Producer prices for machining",
    "PPI-C2511": "Producer prices for metal structures",
    "PPI-C2594": "Producer prices for fasteners",
    "PPI-C2711": "Producer prices for electric motors",
    "PPI-C2732": "Producer prices for wires and cables",
    "PPI-C2611": "Producer prices for electronic components",
    "PPI-C2612": "Producer prices for loaded boards",
    "PPI-C2815": "Producer prices for bearings and gears",
    "PPI-C241": "Producer prices for basic iron and steel",
    "PPI-C2431": "Producer prices for cold-drawn bars",
    "PPI-C2219": "Producer prices for rubber products",
    "PPI-C2813": "Producer prices for pumps and compressors",
    "PPI-D351": "Electricity producer prices",
    "PPI-D35": "Energy supply producer prices",
    "LCI-C": "Manufacturing labour costs",
    "WB-CU": "Copper",
    "WB-NI": "Nickel",
    "WB-AL": "Aluminium",
    "WB-NGEU": "European natural gas",
    "WB-FEORE": "Iron ore",
    "SMARD-DA": "Day-ahead power prices",
    "CU-NOTATION": "The copper notation",
    "AS-14404": "The 1.4404 alloy surcharge",
    "AS-14301": "The 1.4301 alloy surcharge",
}
THEME_WORDS = {
    "energy": re.compile(r"energy|electricit|power|gas\b", re.I),
    "labour": re.compile(r"wage|labour|labor|salar|personnel|staff cost", re.I),
    "material": re.compile(r"material|steel|iron|copper|nickel|alloy|scrap|raw", re.I),
    "freight": re.compile(r"freight|transport|logistic", re.I),
    "quality": re.compile(r"quality|ppm|complaint|defect|8d", re.I),
    "volume": re.compile(r"volume|quantit|forecast", re.I),
    "capacity": re.compile(r"capacity|lead time|backlog|order book", re.I),
    "currency": re.compile(r"currency|exchange rate|euro|usd|czk|pln|huf|try\b", re.I),
}
ID_RE = re.compile(r"\b(?:idx|quote|offer|sc|qn|po|cost|fc|news|doc|ctr):[\w.:@#/-]*\w")


def themes_in(text):
    """The cost themes a text names (a letter blaming energy and wages: energy, labour)."""
    return [t for t, rx in THEME_WORDS.items() if rx.search(text or "")]


def months_back(month, n):
    y, m = (int(x) for x in month.split("-"))
    m -= n
    while m <= 0:
        m, y = m + 12, y - 1
    return f"{y}-{m:02d}"


def _claim(kind, theme, ids, sentence, figure=None, strength=1.0, for_us=True):
    return {
        "kind": kind,
        "theme": theme,
        "ids": ids,
        "sentence": sentence,
        "figure": figure,
        "strength": strength,
        "for_us": for_us,
    }


class ClaimBank:
    """Arguments for one case, per supplier, ranked; `pick` hands out the next ones to cite."""

    def __init__(self, pkg, case):
        self.pkg, self.case = pkg, case
        self._series_last = {}

    def fact(self, ref):
        return (self.case.get("facts") or {}).get(ref) or (self.pkg.lookup(ref) if self.pkg else None)

    def last_month(self, series):
        if series not in self._series_last:
            rows = self.pkg.query("SELECT last_month FROM index_series WHERE id = ?", (series,)) if self.pkg else []
            self._series_last[series] = rows[0]["last_month"] if rows else None
        return self._series_last[series]

    def index_claim(self, series, weight=1.0):
        """The change of one series over the last 12 months of its data, as the arena checks it."""
        m2 = self.last_month(series)
        if not m2:
            return None
        m1 = months_back(m2, 12)
        a, b = self.fact(f"idx:{series}@{m1}"), self.fact(f"idx:{series}@{m2}")
        if not a or not b or not a.get("value"):
            return None
        pct = (b["value"] / a["value"] - 1) * 100
        name = SERIES_NAME.get(series, f"The index {series}")
        return _claim(
            "index",
            SERIES_THEME.get(series, "market"),
            [f"idx:{series}@{m1}", f"idx:{series}@{m2}"],
            f"{name} changed {pct:+.1f}% from {m1} to {m2} (idx:{series}@{m1}, idx:{series}@{m2}).",
            figure=round(pct, 1),
            strength=abs(pct) * max(weight, 0.2) + (2.0 if pct <= 0 else 0.0),
            for_us=pct <= 0,
        )

    def driver_changes(self, part):
        """[(series, weight, change_pct)] for the part's cost drivers: the basis of a justified increase."""
        out = []
        if not self.pkg:
            return out
        for r in self.pkg.query("SELECT series_id, weight FROM cost_drivers WHERE part_id = ?", (part,)):
            c = self.index_claim(r["series_id"], r["weight"])
            if c:
                out.append((r["series_id"], r["weight"], c["figure"]))
        return out

    def scorecard_claim(self, supplier_id, quality=False):
        ids = self.pkg.ids(f"sc:{supplier_id.split(':')[-1]}@") if self.pkg else []
        if not ids:
            return None
        ref = ids[-1]
        f = self.fact(ref)
        if not f:
            return None
        if quality:
            text = f"Your deliveries ran at {f['ppm']} ppm in the twelve months to {f['quarter']} ({ref})."
        else:
            text = f"Your on-time delivery was {f['otd_pct']}% in the twelve months to {f['quarter']} ({ref})."
        bad = f.get("colour") in ("red", "amber")
        return _claim(
            "scorecard",
            "quality",
            [ref],
            text,
            figure=f["ppm"] if quality else f["otd_pct"],
            strength=3.0 if bad else 0.5,
            for_us=bad,
        )

    def should_cost_claim(self, part, supplier_id):
        n = supplier_id.split(":")[-1]
        for ref in (f"cost:{part.split(':')[-1]}-{n}", f"cost:{part.split(':')[-1]}"):
            f = self.fact(ref)
            if f:
                return _claim(
                    "should_cost",
                    "price",
                    [ref],
                    f"Our should-cost estimate for this part is EUR {f['unit_cost']:.2f} per unit ({ref}).",
                    figure=f["unit_cost"],
                    strength=2.5,
                )
        return None

    def po_claim(self, part, supplier_id):
        if not self.pkg:
            return None
        rows = self.pkg.query(
            "SELECT id, order_date, price FROM po_lines WHERE part_id = ? AND supplier_id = ? "
            "AND price_note IS NOT 'stale_condition' ORDER BY order_date DESC LIMIT 3",
            (part, supplier_id),
        )
        rows = [r for r in rows if self.fact(r["id"])]
        if len(rows) < 2:
            return None
        ids = [r["id"] for r in rows]
        distinct = sorted({round(r["price"], 2) for r in rows})
        if len(distinct) == 1:
            text = f"Our last {len(rows)} orders for this part were at EUR {distinct[0]:.2f} ({', '.join(ids)})."
        else:
            prices = " and ".join(f"EUR {r['price']:.2f}" for r in rows)
            text = f"Our last orders for this part were at {prices} ({', '.join(ids)})."
        return _claim("po_history", "price_history", ids, text, strength=1.5)

    def notice_claim(self, supplier_id):
        doc = self.case.get("trigger_doc")
        f = self.fact(doc) if doc else None
        if not f or f.get("days") is None:
            return None
        ctr = next((r for r in self.case.get("refs", []) if r.startswith("ctr:")), None)
        if not ctr and self.pkg:
            rows = self.pkg.query(
                "SELECT id FROM contracts WHERE supplier_id = ? ORDER BY valid_to DESC LIMIT 1", (supplier_id,)
            )
            ctr = rows[0]["id"] if rows else None
        c = self.fact(ctr) if ctr else None
        if not c or c.get("days") is None:
            return None
        short = f["days"] < c["days"]
        return _claim(
            "notice",
            "notice",
            [doc, ctr],
            f"Your letter gives {f['days']} days' notice ({doc}); our agreement provides for {c['days']} days ({ctr}).",
            figure=f["days"],
            strength=4.0 if short else 0.3,
            for_us=short,
        )

    def forecast_claim(self, part):
        ids = self.pkg.ids(f"fc:{part.split(':')[-1]}@") if self.pkg else []
        if not ids:
            return None
        ref = ids[-1]
        f = self.fact(ref)
        if not f or f.get("change_pct") is None or f["change_pct"] <= 0:
            return None
        return _claim(
            "forecast",
            "volume",
            [ref],
            f"Our forecast for this part changed {f['change_pct']:+.1f}% ({ref}).",
            figure=f["change_pct"],
            strength=1.0 + f["change_pct"] / 10,
        )

    def news_claims(self, supplier_id):
        if not self.pkg:
            return []
        rows = self.pkg.query(
            "SELECT id, topic, headline FROM news WHERE supplier_id = ? AND topic <> 'noise' "
            "ORDER BY date DESC LIMIT 2",
            (supplier_id,),
        )
        return [
            _claim("news", "context", [r["id"]], f"We read that {r['headline'].rstrip('.')} ({r['id']}).", strength=0.8)
            for r in rows
            if self.fact(r["id"])
        ]

    def quote_claims(self, supplier_id, part, their_price=None):
        out = []
        for ref in self.case.get("refs", []):
            f = self.fact(ref) if ref.startswith("quote:") else None
            if f and f.get("supplier") == supplier_id and f.get("part") == part:
                out.append(
                    _claim(
                        "quote",
                        "price_history",
                        [ref],
                        f"Your quote of {f.get('date')} was at EUR {f['unit_price']:.2f} per unit ({ref}).",
                        figure=f["unit_price"],
                        strength=1.2,
                    )
                )
        alt = self.case.get("buyer", {}).get("alternative") or {}
        f = self.fact(alt["ref"]) if alt.get("kind") == "quote" and alt.get("ref") else None
        if f and f.get("supplier") != supplier_id and f.get("part") == part:
            out.append(
                _claim(
                    "alternative",
                    "competition",
                    [alt["ref"]],
                    f"We hold a quote at EUR {f['unit_price']:.2f} per unit for this part ({alt['ref']}).",
                    figure=f["unit_price"],
                    strength=3.0,
                    for_us=their_price is None or f["unit_price"] < their_price,
                )
            )
        return out

    def rival_claims(self, supplier_id, threads):
        """Other bidders' standing offers in this session (RFQ): citable to everyone but their author."""
        from arena_kit.play import latest, standing

        out = []
        mine = standing(threads[supplier_id])[1].get("unit_price") if supplier_id in threads else None
        for sid, events in threads.items():
            if sid == supplier_id or latest(events).get("status") in ("walked_away", "no_bid"):
                continue
            offer_id, terms = standing(events)
            if offer_id and terms.get("unit_price") and (mine is None or terms["unit_price"] < mine):
                out.append(
                    _claim(
                        "rival",
                        "competition",
                        [offer_id],
                        f"Another bidder quotes EUR {terms['unit_price']:.2f} per unit for this part ({offer_id}).",
                        figure=terms["unit_price"],
                        strength=3.5,
                    )
                )
        return out

    def for_supplier(self, supplier_id, persona, threads=None):
        """Every claim that fits this case and this supplier, strongest first."""
        case, goal = self.case, self.case.get("buyer", {}).get("category_goal")
        guard = persona.get("relationship", {})
        parts = case.get("parts") or []
        their_price = None
        if threads and supplier_id in threads:
            from arena_kit.play import standing

            their_price = standing(threads[supplier_id])[1].get("unit_price")
        out = []
        for part in parts:
            for series, weight, _ in self.driver_changes(part):
                c = self.index_claim(series, weight)
                if c:
                    out.append(c)
            if goal in ("leverage", "routine") or case.get("type") in ("rfq", "bundling"):
                if (c := self.should_cost_claim(part, supplier_id)) and not guard.get("protect"):
                    out.append(c)
            if case.get("type") in ("price_increase", "renewal", "raw_material"):
                if c := self.po_claim(part, supplier_id):
