            "should_cost",
            "price",
            [ref],
            f"Our should-cost estimate for this part is EUR {f['unit_cost']:.2f} per unit ({ref}).",
            figure=f["unit_cost"],
            strength=2.5,
        )

    def po_claim(self, part, supplier_id):
