        rows = [
            (r["id"], self.fact(r["id"]))
            for r in self.query(
                "SELECT id FROM po_lines WHERE part_id = ? AND supplier_id = ? "
                "AND price_note IS NOT 'stale_condition' ORDER BY order_date DESC LIMIT 3",
